/* eslint-disable react-refresh/only-export-components --
   Same shape, same reason as foundation-context.tsx: one concept's contract,
   defaults, provider and hooks belong in one module. Splitting them to satisfy
   Fast Refresh would put the interface in one file and its only implementation
   in another, for a dev-ergonomics win on a file that changes rarely. */
"use client"

import * as React from "react"

import { DEFAULT_STATE_SPEEDS, type OrbState } from "./kit-vocabulary"

/**
 * THE AMBIENT LAYER'S RUNTIME — everything it needs from a design system, and
 * nothing else.
 *
 * The layer used to read the Foundation directly. That was correct while both
 * lived in one app and fatal the moment anyone wanted the layer without it:
 * eight files importing `@/foundation/foundation-context` is eight hard
 * dependencies on 792 lines of configurator, to consume seven values.
 *
 * So the dependency is inverted. This file states the contract; the Foundation
 * *implements* it (see the bridge in foundation-context.tsx). The layer now
 * asks for what it needs rather than reaching for where it happens to live.
 *
 * THE CONTEXT HAS A REAL DEFAULT AND THE HOOK NEVER THROWS. That is the whole
 * point, and the deliberate opposite of `useFoundation()`, which throws
 * outside its provider. `<Assistant />` mounted in a bare app must render and
 * animate correctly on these values — if it ever cannot, this file is wrong,
 * not the app.
 *
 * The defaults below are not invented. They mirror two existing sources and
 * must keep mirroring them:
 *   · the motion numbers = the "productive" character in foundation-context.tsx
 *     and the `--motion-*` block in packages/ui globals.css (both 120/180/240/
 *     320ms on cubic-bezier(0.2, 0, 0, 1))
 *   · the orb cadence = DEFAULT_STATE_SPEEDS, imported rather than restated
 * Two copies of one value is this project's named failure mode; where a copy is
 * unavoidable, the comment naming the other copy is the mitigation.
 */

export type MotionRole = "micro" | "control" | "surface" | "page"

export type AmbientEase = [number, number, number, number]

export type AmbientTransition = { duration: number; ease: AmbientEase }

export type AmbientSpring = {
  type: "spring"
  stiffness: number
  damping: number
}

export interface AmbientRuntime {
  /**
   * Where the layer's own static assets are served from — the orb's shader
   * shapes (orb-circle.svg and the rect family), which the registry installs
   * into the host's `public/`.
   *
   * It is a value rather than a hardcoded "/" because a site served from a
   * subpath (GitHub Pages project sites, any app mounted under a prefix)
   * resolves a root-absolute URL against the DOMAIN, not the app — so the
   * shader silently loads nothing and the orb goes cold. Default "/" is
   * correct for an app at the root, which is most of them.
   */
  assetBase: string
  /** How a message is presented — see MessagePair. */
  messageVariant: "bubble" | "flat"
  /** The pace StreamingText types at. */
  streamCharsPerSecond: number
  /** The orb's palette and per-state cadence. */
  orb: {
    useAccent: boolean
    colors: string[]
    speeds: Record<OrbState, number>
  }
  /** The framer-motion tween for a motion role (DESIGN.md §5). */
  motionTransition: (role: MotionRole) => AmbientTransition
  /** The spring for interruptible/gestural motion. */
  motionSpring: () => AmbientSpring
}

/* Mirrors globals.css `:root` and the "productive" motion character. */
const DEFAULT_DURATIONS_MS: Record<MotionRole, number> = {
  micro: 120,
  control: 180,
  surface: 240,
  page: 320,
}
const DEFAULT_EASE: AmbientEase = [0.2, 0, 0, 1]

export const DEFAULT_AMBIENT_RUNTIME: AmbientRuntime = {
  assetBase: "/",
  messageVariant: "bubble",
  streamCharsPerSecond: 60,
  orb: {
    useAccent: true,
    colors: ["#8bd8ff", "#2563eb", "#0b1e55"],
    speeds: DEFAULT_STATE_SPEEDS,
  },
  motionTransition: (role) => ({
    duration: DEFAULT_DURATIONS_MS[role] / 1000,
    ease: DEFAULT_EASE,
  }),
  motionSpring: () => ({ type: "spring", stiffness: 380, damping: 32 }),
}

const AmbientRuntimeContext = React.createContext<AmbientRuntime>(
  DEFAULT_AMBIENT_RUNTIME
)

/**
 * Supplies a runtime. Anything omitted falls back to the default, so a host
 * can override the stream pace without knowing what a motion role is.
 */
export function AmbientRuntimeProvider({
  value,
  children,
}: {
  value?: Partial<AmbientRuntime>
  children: React.ReactNode
}) {
  const runtime = React.useMemo<AmbientRuntime>(
    () => (value ? { ...DEFAULT_AMBIENT_RUNTIME, ...value } : DEFAULT_AMBIENT_RUNTIME),
    [value]
  )
  return (
    <AmbientRuntimeContext.Provider value={runtime}>
      {children}
    </AmbientRuntimeContext.Provider>
  )
}

/** Never throws — see the header. A bare mount is a supported configuration. */
export function useAmbientRuntime() {
  return React.useContext(AmbientRuntimeContext)
}

/** The framer-motion tween for a motion role. */
export function useMotionTransition(role: MotionRole) {
  return useAmbientRuntime().motionTransition(role)
}

/** The configured character's spring. */
export function useMotionSpring() {
  return useAmbientRuntime().motionSpring()
}

/**
 * Resolve one of the layer's own assets against the host's base. Tolerates a
 * base with or without its trailing slash, because both spellings are common
 * and the failure (a doubled or missing slash) is silent.
 */
export function useAmbientAsset(file: string) {
  const base = useAmbientRuntime().assetBase
  return `${base.replace(/\/$/, "")}/${file.replace(/^\//, "")}`
}

"use client"

import * as React from "react"

import { AnimatePresence, motion } from "framer-motion"

import { Icon } from "@/components/ui/icon"
import { cn } from "@/lib/utils"

import { useMotionTransition } from "./ambient-runtime"

import { StageSkeleton, StagedItem } from "./staging"
import { StreamingText } from "./streaming-text"
import { useElapsedSeconds, useStagedReveal } from "./use-staged-reveal"

/**
 * THE KNOWLEDGE KIT — where an answer came from.
 *
 * ReferenceChips already answers "what grounded this reply" at the end. These
 * three go further in: what was searched and read as it happened, which
 * SENTENCE rests on which source, and how a long report accumulates.
 *
 * The rule they share: PROVENANCE IS SHOWN, NEVER IMPLIED. A source appears
 * because it was actually read, a citation marks the specific claim it
 * supports, and a section that has not been written yet says so rather than
 * rendering an empty confident heading.
 */

/* ------------------------------ web search ------------------------------ */

export interface SearchSource {
  title: string
  /** The domain, shown as the source's identity: "react.dev". */
  domain: string
  href?: string
  /** A logo the caller supplies; falls back to the domain's initial. */
  logo?: string
}

// keyed by logo at the call site — see RefMark; a different logo is a
// different mark, not the same one in a new state
function SourceMark({ source }: { source: SearchSource }) {
  const [failed, setFailed] = React.useState(false)
  if (source.logo && !failed) {
    return (
      <img
        src={source.logo}
        alt=""
        loading="lazy"
        onError={() => setFailed(true)}
        className="size-4 shrink-0 rounded-sm object-contain"
      />
    )
  }
  return (
    <span
      aria-hidden
      className="bg-muted text-muted-foreground flex size-4 shrink-0 items-center justify-center rounded-sm text-[0.625rem] font-medium uppercase"
    >
      {source.domain.trim().charAt(0)}
    </span>
  )
}

/**
 * WEB SEARCH — the query, then the sources landing one by one as they are
 * read.
 *
 * Showing the QUERY is the point most search UIs skip: it is the assistant's
 * interpretation of the question, and it is the first place an answer goes
 * wrong. Results arrive staggered because they genuinely arrive that way —
 * the animation is reporting, not decoration.
 */
export function WebSearch({
  query,
  sources,
  label,
  staged = true,
  className,
}: {
  query: string
  sources: SearchSource[]
  /** Defaults to "Read N sources". */
  label?: string
  /** Stage the arrival — see staging.tsx. False renders settled. */
  staged?: boolean
  className?: string
}) {
  // sources are read one at a time; the count says how far it has got
  const { shown, pending, working: counting } = useStagedReveal(sources.length, {
    enabled: staged,
    delay: 1800,
    interval: 700,
  })
  const elapsed = useElapsedSeconds(counting)
  const reading = staged && shown < sources.length
  return (
    <div className={cn("flex flex-col gap-2", className)}>
      <span className="bg-muted text-foreground inline-flex max-w-full items-center gap-2 self-start rounded-full px-3 py-1.5 text-sm">
        <Icon name="search" size={13} />
        <span className={cn("min-w-0 truncate", reading && "ambient-shimmer")}>
          {query}
        </span>
      </span>
      {sources.length > 0 && (
        <>
          <div
            className={cn(
              "text-muted-foreground text-sm",
              reading && "ambient-shimmer"
            )}
          >
            {reading
              ? `Reading sources… ${elapsed}s`
              : (label ??
                `Read ${shown} source${shown === 1 ? "" : "s"}`)}
          </div>
          {pending && <StageSkeleton rows={2} />}
          <ul className="flex flex-col gap-1">
            {sources.slice(0, shown).map((s, i) => {
              const inner = (
                <>
                  <SourceMark key={s.logo ?? "none"} source={s} />
                  <span className="min-w-0 flex-1 truncate text-sm">
                    {s.title}
                  </span>
                  <span className="text-muted-foreground shrink-0 font-mono text-xs">
                    {s.domain}
                  </span>
                </>
              )
              return (
                <li key={`${s.domain}-${i}`}>
                  <StagedItem index={i}>
                  {s.href ? (
                    <a
                      href={s.href}
                      target="_blank"
                      rel="noreferrer"
                      className="hover:bg-muted flex items-center gap-2 rounded-lg px-1.5 py-1 transition-colors"
                    >
                      {inner}
                    </a>
                  ) : (
                    <span className="flex items-center gap-2 px-1.5 py-1">
                      {inner}
                    </span>
                  )}
                  </StagedItem>
                </li>
              )
            })}
          </ul>
        </>
      )}
    </div>
  )
}

/* --------------------------- inline citation ---------------------------- */

export interface Citation {
  n: number
  title: string
  domain: string
  excerpt?: string
  href?: string
}

/**
 * INLINE CITATION — a numbered reference attached to the CLAIM it supports.
 *
 * Reference chips at the end of an answer say the reply used these sources.
 * A citation says THIS sentence rests on THIS one, which is the difference
 * between provenance and a bibliography. It costs a superscript inline and
 * shows the excerpt on hover, so verification never leaves the sentence.
 */
export function InlineCitation({
  citation,
  className,
}: {
  citation: Citation
  className?: string
}) {
  const [open, setOpen] = React.useState(false)
  const transition = useMotionTransition("control")
  const Tag = citation.href ? "a" : "button"
  return (
    <span className={cn("relative inline-block align-baseline", className)}>
      <Tag
        {...(citation.href
          ? { href: citation.href, target: "_blank", rel: "noreferrer" }
          : { type: "button" as const })}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        aria-label={`Source ${citation.n}: ${citation.title}`}
        className={cn(
          // NOT align-super: superscript alignment stretches the line box and
          // pads every paragraph that contains a citation. A baseline-aligned
          // marker nudged up costs the prose nothing.
          "relative -top-[0.35em] mx-0.5 inline-flex min-w-4 items-center justify-center rounded px-1 py-0.5 align-baseline font-mono text-[0.625rem] leading-none transition-colors",
          open
            ? "bg-foreground text-background"
            : "bg-muted text-muted-foreground"
        )}
      >
        {citation.n}
      </Tag>
      <AnimatePresence>
        {open && (
          <motion.span
            initial={{ opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 4 }}
            transition={transition}
            role="tooltip"
            // the preview sits ABOVE the line: a citation is read mid-sentence,
            // and a card below would cover the text still being read
            className="border-border bg-card absolute bottom-full left-0 z-10 mb-1.5 flex w-64 flex-col gap-1 rounded-xl border p-3 shadow-xs"
          >
            <span className="text-muted-foreground flex items-center gap-1.5 font-mono text-xs">
              <span className="bg-muted text-muted-foreground flex size-4 shrink-0 items-center justify-center rounded-sm text-[0.625rem] font-medium uppercase">
                {citation.domain.charAt(0)}
              </span>
              {citation.domain}
            </span>
            <span className="text-sm font-medium">{citation.title}</span>
            {citation.excerpt && (
              <span className="text-muted-foreground text-sm">
                {citation.excerpt}
              </span>
            )}
          </motion.span>
        )}
      </AnimatePresence>
    </span>
  )
}

/* --------------------------- research report ---------------------------- */

export interface ReportSection {
  title: string
  body?: string
  status?: "done" | "running" | "pending"
  /** How many sources this section rests on. */
  sources?: number
}

/**
 * RESEARCH REPORT — an outline that fills in section by section.
 *
 * A long report streamed as one block gives no sense of progress or shape.
 * Declaring the outline first turns waiting into reading: you can see what
 * is coming, what is being written now, and what has landed — and each
 * finished section carries the number of sources behind it, so depth is
 * legible per claim rather than as one total at the end.
 */
export function ResearchReport({
  title,
  sections,
  sourcesRead,
  staged = true,
  className,
}: {
  title: string
  sections: ReportSection[]
  /** Total sources read so far, shown in the header. */
  sourcesRead?: number
  /** Stage the arrival — see staging.tsx. False renders settled. */
  staged?: boolean
  className?: string
}) {
  // the outline is declared first and fills in; that IS the component's claim
  const { shown, pending, working: counting } = useStagedReveal(sections.length, {
    enabled: staged,
    delay: 2000,
    interval: 1400,
  })
  const writing = staged && shown < sections.length
  const elapsed = useElapsedSeconds(counting)
  const landed = sections.slice(0, shown)
  const done = landed.filter((s) => (s.status ?? "pending") === "done").length
  return (
    <div
      className={cn(
        "border-border bg-card overflow-hidden rounded-xl border",
        className
      )}
    >
      <div className="px-3 pt-3 pb-2">
        <div className="text-sm font-medium">{title}</div>
        <div
          className={cn(
            "text-muted-foreground mt-0.5 font-mono text-xs tabular-nums",
            writing && "ambient-shimmer"
          )}
        >
          {writing
            ? `Researching… ${elapsed}s · ${done}/${sections.length} sections`
            : `${done}/${sections.length} sections${
                sourcesRead !== undefined ? ` · ${sourcesRead} sources read` : ""
              }`}
        </div>
      </div>
      {pending && <StageSkeleton rows={2} className="px-3 pb-3" />}
      <ol className="divide-border divide-y">
        {landed.map((s, si) => {
          const status = s.status ?? "pending"
          return (
            <StagedItem
              key={s.title}
              index={si}
              className="flex gap-2.5 px-3 py-2.5"
            >
              <span className="mt-0.5 shrink-0">
                {status === "done" ? (
                  <span className="text-(--positive)">
                    <Icon name="check" size={14} />
                  </span>
                ) : status === "running" ? (
                  <span className="border-muted-foreground/30 border-t-primary block size-3.5 animate-spin rounded-full border-2" />
                ) : (
                  <span
                    aria-hidden
                    className="bg-muted-foreground/40 mt-1 block size-1.5 rounded-full"
                  />
                )}
              </span>
              <div className="min-w-0 flex-1">
                <div className="flex items-baseline justify-between gap-3">
                  <span
                    className={cn(
                      "text-sm font-medium",
                      status === "pending" && "text-muted-foreground"
                    )}
                  >
                    {s.title}
                  </span>
                  {s.sources !== undefined && (
                    <span className="text-muted-foreground shrink-0 font-mono text-xs">
                      {s.sources} src
                    </span>
                  )}
                </div>
                {s.body && (
                  // a section is written, so it arrives written
                  <StreamingText
                    text={s.body}
                    live={staged}
                    className="text-muted-foreground mt-0.5 block text-sm"
                  />
                )}
              </div>
            </StagedItem>
          )
        })}
      </ol>
    </div>
  )
}

"use client"

import * as React from "react"

/**
 * THE ONE ORDERING RULE: an answer arrives in sequence, never all at once.
 *
 * Thinking finishes, THEN the next block does its work, THEN the prose
 * streams. Before this, every staged block ran its own private timer, so a
 * reasoning panel, a tool call and the answer text all raced — the sentence
 * explaining the work appeared while the work was still visibly spinning.
 * That reads as theatre, because it is: nothing was waiting on anything.
 *
 * The queue is a strict order, not a schedule. Each staged block claims a
 * slot in mount order and is held at its shimmer until every slot before it
 * has reported finished. `useStagedReveal` does the claiming, so a block
 * inherits the rule by being staged at all — there is nothing for an
 * individual block to remember, and nothing it can opt out of by accident.
 *
 * Outside a provider (a /ds playground, a lone block) `isTurn` is never
 * consulted and blocks stage immediately, which is the right behavior for a
 * block standing on its own.
 */

export type StageQueue = {
  register: (id: string) => void
  unregister: (id: string) => void
  finish: (id: string) => void
  /** True once every block that registered before `id` has finished. */
  isTurn: (id: string) => boolean
}

export const StageQueueContext = React.createContext<StageQueue | null>(null)

/**
 * Held by whatever owns the sequence (ResponseBlock). `settled` is the gate
 * for what comes AFTER the queue — the answer text waits on it.
 *
 * `expected` is how many blocks the owner actually rendered, and the gate is
 * counted against THAT rather than against the registration list. The list is
 * built from mount effects, so anything that perturbs it — a remount, a block
 * that leaves — could otherwise leave the gate waiting on a slot nobody is
 * standing in. The owner's count cannot drift: it is the array it mapped.
 */
export function useStageQueue(expected = 0) {
  // arrays, not Sets: the order IS the data, and a new array per change is
  // what makes `isTurn` recompute for the blocks waiting on it
  const [order, setOrder] = React.useState<string[]>([])
  const [done, setDone] = React.useState<string[]>([])

  const register = React.useCallback((id: string) => {
    setOrder((o) => (o.includes(id) ? o : [...o, id]))
  }, [])

  const unregister = React.useCallback((id: string) => {
    // a block that leaves must not hold the queue behind it forever
    setOrder((o) => o.filter((x) => x !== id))
    setDone((d) => d.filter((x) => x !== id))
  }, [])

  const finish = React.useCallback((id: string) => {
    setDone((d) => (d.includes(id) ? d : [...d, id]))
  }, [])

  const isTurn = React.useCallback(
    (id: string) => {
      const i = order.indexOf(id)
      // not registered yet: hold at the shimmer rather than jumping the line
      if (i < 0) return false
      return order.slice(0, i).every((x) => done.includes(x))
    },
    [order, done]
  )

  const queue = React.useMemo(
    () => ({ register, unregister, finish, isTurn }),
    [register, unregister, finish, isTurn]
  )

  return {
    queue,
    /** As many blocks have finished as the owner put in. */
    settled: expected > 0 && done.length >= expected,
  }
}

"use client"

import * as React from "react"

import { motion } from "framer-motion"

import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"

import { useMotionTransition } from "./ambient-runtime"

/**
 * The two rendering halves of staged arrival; the hook that drives them is
 * use-staged-reveal.ts (a file that exports both a hook and components loses
 * Fast Refresh for everything importing it).
 */

/** The shimmer stand-in, sized to the rows it is standing in for. */
export function StageSkeleton({
  rows = 2,
  className,
}: {
  rows?: number
  className?: string
}) {
  return (
    <div className={cn("flex flex-col gap-2 pt-3", className)} aria-hidden>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-start gap-2.5">
          <Skeleton className="mt-1.5 size-1.5 rounded-full" />
          <div className="flex min-w-0 flex-1 flex-col gap-1.5">
            <Skeleton className="h-3 rounded-md" style={{ width: "38%" }} />
            <Skeleton
              className="h-3 rounded-md"
              style={{ width: i % 2 ? "72%" : "88%" }}
            />
          </div>
        </div>
      ))}
    </div>
  )
}

/**
 * One item landing. Subtle on purpose: this is reporting, not choreography.
 *
 * Height animates alongside opacity because the row below is what the eye is
 * actually resting on — a row that appears at full height shoves everything
 * under it in a single frame, and that jump reads as jank no matter how the
 * row itself fades. The outer div owns the reveal (height + clip), the inner
 * div owns the layout, so flex rows never fight the overflow clip.
 */
export function StagedItem({
  index = 0,
  children,
  className,
}: {
  index?: number
  children: React.ReactNode
  className?: string
}) {
  const transition = useMotionTransition("control")
  return (
    <motion.div
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: "auto" }}
      transition={transition}
      className="overflow-hidden"
      data-stage-index={index}
    >
      <motion.div
        initial={{ y: 6 }}
        animate={{ y: 0 }}
        transition={transition}
        className={className}
      >
        {children}
      </motion.div>
    </motion.div>
  )
}

/** The line a block shows while it is still working. */
export function StageLabel({
  children,
  className,
}: {
  children: React.ReactNode
  className?: string
}) {
  return (
    <span className={cn("ambient-shimmer text-sm", className)}>
      {children}
    </span>
  )
}

"use client"

import * as React from "react"

import { useAnimationFrame } from "framer-motion"


import { useAmbientRuntime } from "./ambient-runtime"

/**
 * STREAMING TEXT — text that arrives rather than appears.
 *
 * Three zones travel with the write head: settled text in the foreground,
 * a warm tail in the ambient accent, and a blurred edge behind a fading
 * mask. The reveal runs on the FRAME CLOCK, not a timer, and derives its
 * position from ELAPSED TIME rather than by counting ticks. A hidden tab
 * pauses the frame loop either way; what this buys is the recovery — coming
 * back, the write head is where the clock says it should be, instead of
 * however far a throttled timer happened to count.
 *
 * `live={false}` renders the whole string settled — history is written,
 * not replayed, so a re-rendered older message never re-types itself.
 */
/** How many characters trail behind the write head, warm then blurred. */
const TAIL = 26
const EDGE = 8

export function StreamingText({
  text,
  live = true,
  charsPerSecond,
  onSettled,
  className,
}: {
  text: string
  live?: boolean
  /**
   * Override the runtime pace (streamCharsPerSecond). The
   * default reads as deliberate writing, not a printer.
   */
  charsPerSecond?: number
  onSettled?: () => void
  className?: string
}) {
  // THE COMPONENT-LAYER CONFIG: the pace is a saved product decision, so the
  // prop is an override, not the source of truth. Same rule as the orb's
  // palette — the rail edits the theme, the theme drives every instance.
  const runtime = useAmbientRuntime()
  const cps = charsPerSecond ?? runtime.streamCharsPerSecond
  const [shown, setShown] = React.useState(() => (live ? 0 : text.length))
  const settledRef = React.useRef(!live)
  const onSettledRef = React.useRef(onSettled)
  // the frame loop calls this without re-subscribing; refreshed after commit
  React.useEffect(() => {
    onSettledRef.current = onSettled
  })
  const startRef = React.useRef<number | null>(null)

  useAnimationFrame((t) => {
    if (settledRef.current || !live) return
    if (startRef.current === null) startRef.current = t
    const next = Math.min(
      text.length,
      Math.floor(((t - startRef.current) / 1000) * cps)
    )
    setShown(next)
    if (next >= text.length) {
      settledRef.current = true
      window.setTimeout(() => onSettledRef.current?.(), 400)
    }
  })

  const done = shown >= text.length

  return (
    <span className={className}>
      {text.slice(0, done ? text.length : Math.max(0, shown - TAIL))}
      {!done && (
        <>
          <span className="ambient-stream-warm">
            {text.slice(Math.max(0, shown - TAIL), Math.max(0, shown - EDGE))}
          </span>
          <span className="ambient-stream-edge">
            {text.slice(Math.max(0, shown - EDGE), shown)}
          </span>
          <span className="bg-primary ms-0.5 inline-block h-3.5 w-0.5 animate-pulse align-middle" />
        </>
      )}
    </span>
  )
}

"use client"

import * as React from "react"

import { StageQueueContext } from "./stage-queue"

/**
 * STAGED ARRIVAL — how every evidence block admits that it took time.
 *
 * A reasoning trace, a batch of tool calls, a list of sources: all of them
 * arrive complete in the code and would paint in one frame. Painting them
 * instantly is a small lie — it says the work was free — and it also robs the
 * reader of the one thing the block is for, which is watching the assistant
 * think.
 *
 * So every block stages the same way:
 *
 *   1. SHIMMER while there is nothing yet. The placeholder carries the
 *      ambient accent (see .ambient-shimmer), so waiting is the assistant's
 *      identity rather than generic grey.
 *   2. HOLD, because a beat of nothing is what makes the arrival read as an
 *      arrival.
 *   3. ONE AT A TIME, each item on the control motion role.
 *
 * And blocks wait for EACH OTHER: inside a response the hook claims a slot in
 * the stage queue and holds at its shimmer until every earlier block has
 * finished (see stage-queue.ts). Thinking completes, then the next block
 * works, then the answer streams — one sequence rather than a race.
 *
 * This lives in one place so the blocks cannot drift into three different
 * ideas of what waiting looks like.
 */

export interface StageOptions {
  /** How long the shimmer holds before the first item lands. */
  delay?: number
  /** Gap between items. */
  interval?: number
  /** Pass false to render settled — history is written, not replayed. */
  enabled?: boolean
  /** Bump to perform the arrival again — a re-run is a new arrival. */
  replay?: number
  /**
   * Hold the working state for at least this long, even after every item has
   * landed. Thinking that finishes in a blink reads as a lookup, not as work
   * — and because the hold is REAL, the counter measuring it stays honest.
   */
  minDuration?: number
}

/**
 * Returns how many of `count` items should be visible, and whether the block
 * is still in its shimmer. Settled when `enabled` is false, so a re-rendered
 * older message never performs its arrival again.
 */
export function useStagedReveal(count: number, options: StageOptions = {}) {
  const {
    delay = 700,
    interval = 320,
    enabled = true,
    replay = 0,
    minDuration = 0,
  } = options
  const [shown, setShown] = React.useState(enabled ? 0 : count)

  // THE QUEUE. A slot is claimed on mount, so slots are handed out in mount
  // order — which for the sibling blocks of one answer is reading order. With
  // no provider above (a /ds playground, a lone block) there is no queue and
  // the block simply stages.
  const queue = React.useContext(StageQueueContext)
  const id = React.useId()
  // Depend on the CALLBACKS, never on the queue object: its identity changes
  // every time any block registers or finishes (isTurn closes over the
  // order), so an effect keyed on it would unregister and re-register this
  // block on every change — shuffling it to the back of a line it is already
  // standing in, forever.
  const register = queue?.register
  const unregister = queue?.unregister
  React.useEffect(() => {
    if (!register || !unregister) return
    register(id)
    return () => unregister(id)
  }, [register, unregister, id])
  const waiting = enabled && Boolean(queue) && !queue!.isTurn(id)
  // running = this block's turn has come AND it stages at all
  const running = enabled && !waiting

  // A changed input starts the arrival over. Adjusted DURING render, not from
  // an effect: resetting to 0 after the fact paints one frame of the finished
  // list before the shimmer.
  const scope = `${count}|${delay}|${interval}|${running}|${replay}|${minDuration}`
  const [floorMet, setFloorMet] = React.useState(!minDuration)
  const [scopeSeen, setScopeSeen] = React.useState(scope)
  if (scope !== scopeSeen) {
    setScopeSeen(scope)
    setShown(enabled ? 0 : count)
    setFloorMet(!minDuration)
  }

  React.useEffect(() => {
    if (!running || !minDuration) return
    const id = window.setTimeout(() => setFloorMet(true), minDuration)
    return () => window.clearTimeout(id)
  }, [scope, running, minDuration])

  React.useEffect(() => {
    if (!running) return
    const timers: number[] = []
    for (let i = 0; i < count; i++) {
      timers.push(
        window.setTimeout(() => setShown(i + 1), delay + i * interval)
      )
    }
    return () => timers.forEach(window.clearTimeout)
  }, [scope, count, delay, interval, running])

  // hand the queue on the moment this block has nothing left to reveal — a
  // settled block (enabled false) was never in the running, so it yields at once
  const complete = !enabled || (shown >= count && floorMet)
  const finish = queue?.finish
  React.useEffect(() => {
    if (finish && complete) finish(id)
  }, [finish, complete, id])

  return {
    shown,
    pending: shown === 0,
    /** Holding for an earlier block. Shimmering, but not yet working. */
    waiting,
    /**
     * Actually producing something right now — its turn has come and it has
     * items left to reveal. THIS is what an elapsed counter runs on: false
     * while queued (someone else's time) and false once complete (so the
     * settled summary quotes a measurement that has stopped moving).
     */
    working: running && (shown < count || !floorMet),
  }
}

/**
 * Seconds elapsed since `active` became true, ticking once a second.
 *
 * Pass the block's WORKING flag, never just `staged`: a block held in the
 * stage queue is not working yet, and a counter that ran through the wait
 * would quote someone else's time as its own.
 *
 * The count is REAL: a trace that claims "thought for 5s" while it took two is
 * a decoration pretending to be a measurement. It freezes at the final value
 * when the work ends, which is the number the settled summary then quotes.
 */
export function useElapsedSeconds(active: boolean) {
  const [elapsed, setElapsed] = React.useState(0)
  const startedRef = React.useRef<number | null>(null)

  React.useEffect(() => {
    if (!active) return
    startedRef.current = performance.now()
    const id = window.setInterval(() => {
      const started = startedRef.current
      if (started !== null) setElapsed(Math.round((performance.now() - started) / 1000))
    }, 250)
    return () => window.clearInterval(id)
  }, [active])

  return elapsed
}
